-- Source tables: one per benchmark table, every CDC arm captures all of
-- them. The loader writes a fixed-rate INSERT/UPDATE/DELETE mix into each
-- (see ../loader). Row shape is fixed (id bigint PRIMARY KEY, payload
-- text) and identical across tables and arms.
--
-- REPLICA IDENTITY stays DEFAULT (the primary key), so pgoutput emits the
-- key for deletes and all three systems can reconstruct the changed row.
--
-- GENERATED by scripts/generate.sh from TABLES (committed copy is the
-- TABLES=1 default); run.sh regenerates it. Do not edit by hand.
CREATE TABLE bench_source_0 (
    id      bigint PRIMARY KEY,
    payload text   NOT NULL
);
